WITH product_summary AS (SELECT product_id, SUM(quantity) AS total_quantity, MAX(last_restock) AS last_last_restock FROM inventory WHERE product_id IN (1, 7) GROUP BY product_id) SELECT products.id, products.supplier_id, products.cost, product_summary.total_quantity, product_summary.last_last_restock FROM products INNER JOIN product_summary ON products.id = product_summary.product_id WHERE product_summary.total_quantity > 780 ORDER BY products.cost ASC, id ASC LIMIT 5
